const payload = $input.first().json;
const original = payload.media?.original;
const event = payload.event;
if (!event?.event_id || !event?.source_post_id || !original?.public_url || !original?.sha256 || !original?.mime_type) {
  throw new Error('SOCIAL_MEDIA_STAGING_INPUT_INVALID');
}
if (!['image/jpeg', 'image/png', 'image/webp'].includes(original.mime_type)) {
  throw new Error('SOCIAL_MEDIA_STAGING_MIME_UNSUPPORTED');
}
const extension = { 'image/jpeg': 'jpg', 'image/png': 'png', 'image/webp': 'webp' }[original.mime_type];
const sourceSite = event.source_site || 'OPURO';
const objectKey = `social/v1/${sourceSite}/${event.source_post_id}/${original.sha256}/original.${extension}`;
return [{ json: { ...payload, staging: { object_key: objectKey, expected_sha256: original.sha256, source_url: original.public_url, mime_type: original.mime_type } } }];

const source = $node['Validate + Derive Immutable Key'].json;
const base = $vars.OPMX_SOCIAL_PUBLIC_BASE_URL;
if (!base || !/^https:///.test(base)) throw new Error('OPMX_SOCIAL_PUBLIC_BASE_URL_NOT_CONFIGURED');
const publicUrl = `${base.replace(/\/$/, '')}/${source.staging.object_key}`;
return [{ json: { ...source, asset: { public_url: publicUrl, object_key: source.staging.object_key, sha256: source.staging.expected_sha256, mime_type: source.staging.mime_type, immutable: true } } }];
